contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint w) public payable {
        require(w <= type(uint256).max);
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint balAfterAll = address(c).balance;
        bool reverted;
        c.withdraw(w); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balFinal = address(c).balance;
        assert(reverted == (w > 0) && balFinal == 0 && balAfterAll == 0);
    }
    receive() external payable {}
}

