// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 w) internal {
        vm.assume(w <= type(uint256).max);
        try c.withdrawAll() {} catch { return; }
        uint balAfterAll = address(c).balance;
        bool reverted;
        try c.withdraw(w) { reverted = false; } catch { reverted = true; }
        uint balFinal = address(c).balance;
        assertTrue(reverted == (w > 0) && balFinal == 0 && balAfterAll == 0);
    }

    function testFuzz_run(uint256 w) public {
        _run(w);
    }

    receive() external payable {}
}
